"use client"

import * as React from "react"
import { NavigationMenu as NavigationMenuPrimitive } from "@base-ui/react/navigation-menu"
import { cva } from "class-variance-authority"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

// Control Room NavigationMenu: sector tabs along the console header.
// Uppercase triggers; the viewport panel uses the shared glow-elevated
// popover surface.

function NavigationMenu({
  className,
  children,
  ...props
}: NavigationMenuPrimitive.Root.Props) {
  return (
    <NavigationMenuPrimitive.Root
      className={cn(
        "relative z-10 flex max-w-max flex-1 items-center justify-center",
        className
      )}
      {...props}
    >
      {children}
      <NavigationMenuViewport />
    </NavigationMenuPrimitive.Root>
  )
}
NavigationMenu.displayName = "NavigationMenu"

const NavigationMenuList = React.forwardRef<
  HTMLUListElement,
  NavigationMenuPrimitive.List.Props
>(({ className, ...props }, ref) => (
  <NavigationMenuPrimitive.List
    ref={ref}
    className={cn(
      "group flex flex-1 list-none items-center justify-center gap-1",
      className
    )}
    {...props}
  />
))
NavigationMenuList.displayName = "NavigationMenuList"

const NavigationMenuItem = NavigationMenuPrimitive.Item

const navigationMenuTriggerStyle = cva(
  [
    "group inline-flex h-9 w-max items-center justify-center rounded-sm px-3 py-2",
    "text-xs font-semibold uppercase tracking-wider",
    "transition-colors duration-fast",
    "bg-transparent text-muted-foreground",
    "hover:bg-accent hover:text-foreground",
    "focus:bg-accent focus:text-foreground focus:outline-none",
    "disabled:pointer-events-none disabled:opacity-50",
    "data-[active]:text-primary data-popup-open:text-primary",
    "data-[active]:[box-shadow:inset_0_-0.125rem_0_oklch(0.78_0.21_148/0.8)]",
  ].join(" ")
)

const NavigationMenuTrigger = React.forwardRef<
  HTMLButtonElement,
  NavigationMenuPrimitive.Trigger.Props
>(({ className, children, ...props }, ref) => (
  <NavigationMenuPrimitive.Trigger
    ref={ref}
    className={cn(navigationMenuTriggerStyle(), "group", className)}
    {...props}
  >
    {children}{" "}
    <Icon
      icon="tabler:chevron-down"
      className="relative top-px ml-1 size-3 transition duration-base group-data-popup-open:rotate-180"
      aria-hidden="true"
    />
  </NavigationMenuPrimitive.Trigger>
))
NavigationMenuTrigger.displayName = "NavigationMenuTrigger"

const NavigationMenuContent = React.forwardRef<
  HTMLDivElement,
  NavigationMenuPrimitive.Content.Props
>(({ className, ...props }, ref) => (
  <NavigationMenuPrimitive.Content
    ref={ref}
    className={cn(
      "left-0 top-0 w-full p-2 transition-[opacity,transform,translate] duration-fast data-starting-style:opacity-0 data-ending-style:opacity-0 data-starting-style:data-[activation-direction=left]:-translate-x-52 data-starting-style:data-[activation-direction=right]:translate-x-52 data-ending-style:data-[activation-direction=left]:translate-x-52 data-ending-style:data-[activation-direction=right]:-translate-x-52 md:absolute md:w-auto",
      className
    )}
    {...props}
  />
))
NavigationMenuContent.displayName = "NavigationMenuContent"

const NavigationMenuLink = NavigationMenuPrimitive.Link

const NavigationMenuViewport = React.forwardRef<
  HTMLDivElement,
  NavigationMenuPrimitive.Viewport.Props
>(({ className, ...props }, ref) => (
  <NavigationMenuPrimitive.Portal>
    <NavigationMenuPrimitive.Positioner sideOffset={6} className="isolate z-50">
      <NavigationMenuPrimitive.Popup
        className={cn(
          "relative h-[var(--popup-height)] w-full origin-[var(--transform-origin)] overflow-hidden md:w-[var(--popup-width)]",
          "rounded-md border border-border bg-popover text-popover-foreground",
          "[box-shadow:var(--shadow-popover)]",
          "transition-[opacity,transform,scale,width,height] duration-fast data-starting-style:scale-90 data-ending-style:scale-95"
        )}
      >
        <NavigationMenuPrimitive.Viewport
          ref={ref}
          className={cn("relative h-full w-full overflow-hidden", className)}
          {...props}
        />
      </NavigationMenuPrimitive.Popup>
    </NavigationMenuPrimitive.Positioner>
  </NavigationMenuPrimitive.Portal>
))
NavigationMenuViewport.displayName = "NavigationMenuViewport"

// BEHAVIOR DELTA (flagged): Base UI has no equivalent of the upstream
// NavigationMenu.Indicator (the pointer that tracks the active trigger along
// the list). This is an inert passthrough that renders nothing so existing
// call sites keep compiling. The closest Base UI analogues are
// NavigationMenu.Icon (chevron inside the trigger) and NavigationMenu.Arrow
// (popup-anchored pointer), neither of which tracks the trigger list.
function NavigationMenuIndicator(props: React.ComponentPropsWithoutRef<"div">) {
  void props
  return null
}
NavigationMenuIndicator.displayName = "NavigationMenuIndicator"

export {
  navigationMenuTriggerStyle,
  NavigationMenu,
  NavigationMenuList,
  NavigationMenuItem,
  NavigationMenuContent,
  NavigationMenuTrigger,
  NavigationMenuLink,
  NavigationMenuIndicator,
  NavigationMenuViewport,
}
